class Learner:
    def __init__(self, name, xp):
        self.name = name
        self.xp = xp
    def summary(self):
        return f"{self.name}: {self.xp} XP"
print(Learner("Ama", 120).summary())

class Counter:
    def __init__(self):
        self.value = 0
    def add(self, amount=1):
        self.value += amount
c = Counter(); c.add(5); print(c.value)

class Course:
    def __init__(self, title):
        self.title = title
course = Course("Python")
print(course.title)

class PremiumLearner(Learner):
    def badge(self):
        return "Practice champion"
print(PremiumLearner("Kojo", 90).badge())
